$('#opacitySlider').onpointerdown=()=>{if(activeFrame())checkpoint()};$('#opacitySlider').onkeydown=e=>{if(activeFrame()&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key))checkpoint()};$('#opacitySlider').oninput=e=>{const l=activeLayer();if(!l)return;l.opacity=Number(e.target.value)/100;$('#opacityValue').textContent=e.target.value+'%';renderCanvas();setDirty()};$('#sizeSlider').oninput=e=>{S.size=Number(e.target.value);$('#sizeValue').textContent=S.tool==='eraser'?S.size+' px · r '+(S.size/2)+' px':S.size+' px';if(S.cursorPoint)updateEraserCursor(S.cursorPoint.x,S.cursorPoint.y)};$('#colorInput').oninput=e=>{S.color=e.target.value;$('#colorChip').style.background=S.color;$('#colorHex').value=S.color.toUpperCase()};$('#colorChip').style.background=S.color;$('#textColor').value=S.color;$('#colorHex').onchange=e=>{let v=e.target.value.trim();if(!v.startsWith('#'))v='#'+v;if(/^#[0-9a-f]{6}$/i.test(v)){$('#colorInput').value=v;$('#colorChip').style.background=v;S.color=v}else e.target.value=S.color.toUpperCase()};$('#swapColorBtn').onclick=()=>{$('#colorInput').value='#ef865d';$('#colorInput').dispatchEvent(new Event('input'))};
$('#fillMode').onclick=e=>{if(!e.target.matches('button'))return;S.shape=e.target.dataset.mode;$$('#fillMode button').forEach(b=>b.classList.toggle('selected',b===e.target))};
$('#zoomSlider').oninput=e=>setZoom(Number(e.target.value)/100);$('#canvasWorkspace').addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey){e.preventDefault();setZoom(S.zoom*(e.deltaY<0?1.1:1/1.1))}},{passive:false});$('#zoomInBtn').onclick=()=>setZoom(S.zoom*1.2);$('#zoomOutBtn').onclick=()=>setZoom(S.zoom/1.2);$('#fitBtn').onclick=fitCanvas;$('#gridBtn').onclick=()=>{$('#canvasWorkspace').classList.toggle('no-grid');S.grid=!S.grid};$('#bgBtn').onclick=()=>{$('#canvasWorkspace').classList.toggle('alt-bg');S.bgAlt=!S.bgAlt};
$('#cleanEdgesBtn').onclick=()=>cleanEdges();$('#speckSlider').oninput=e=>{S.speckLimit=Number(e.target.value);$('#speckValue').textContent=S.speckLimit+' px'};$('#selectionFeather').oninput=e=>{S.selectionFeather=Number(e.target.value);$('#selectionFeatherValue').textContent=e.target.value+' px'};$('#selectionAntialias').onchange=e=>S.selectionAntialias=e.target.checked;$('#magneticRadius').oninput=e=>{S.magneticRadius=Number(e.target.value);$('#magneticRadiusValue').textContent=e.target.value+' px'};$('#applyTextBtn').onclick=applyTextLayer;$('#playBtn').onclick=togglePlay;$('#sequenceSelect').onchange=e=>{S.seq=e.target.value;const [a,b]=S.seq==='all'?[0,S.frames.length-1]:S.seq.split(':').map(Number);$('#rangeLabel').textContent=S.frames.length?(String(a).padStart(3,'0')+'—'+String(b).padStart(3,'0')):'';$('#sequenceLabel').textContent=S.seq==='all'?'All frames':e.target.selectedOptions[0].textContent;if(S.playing){togglePlay();togglePlay()}};$('#fpsInput').onchange=()=>{if(S.playing){togglePlay();togglePlay()}};$('#onionBtn').onclick=()=>{S.onion=!S.onion;$('#onionBtn').classList.toggle('active',S.onion);renderCanvas();setToast(S.onion?'Onion skin preview enabled':'Onion skin preview disabled')};$('#timelineToggle').onclick=()=>$('.timeline').classList.toggle('collapsed');
$('#downloadJsonBtn').onclick=()=>{if(!S.jsonText){setToast('No source JSON file is loaded.');return}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([S.jsonText],{type:'application/json'}));a.download=S.jsonName||'sprites.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)};
function addMaskButton(){const actions=$('.layer-quick-actions');const b=document.createElement('button');b.id='maskToggle';b.innerHTML='<svg viewBox="0 0 24 24"><path d="M4 5h16v14H4z"/><circle cx="12" cy="12" r="4"/></svg>Mask';b.title='Add or edit the active layer mask';b.onclick=addMask;actions.append(b);const lock=document.createElement('button');lock.id='lockLayerBtn';lock.textContent='Lock';lock.title='Lock or unlock the active layer';lock.onclick=()=>{const l=activeLayer();if(!l)return;l.locked=!l.locked;lock.textContent=l.locked?'Unlock':'Lock';renderLayers()};actions.append(lock)}
addMaskButton();
$('#helpBtn').onclick=()=>$('#helpModal').classList.remove('hidden');$('#closeHelp').onclick=()=>$('#helpModal').classList.add('hidden');$('#helpModal').onclick=e=>{if(e.target.id==='helpModal')$('#helpModal').classList.add('hidden')};
window.addEventListener('keydown',e=>{const tag=document.activeElement?.tagName;if(tag==='INPUT'||tag==='TEXTAREA'||tag==='SELECT')return;const mod=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(mod&&e.key==='+'){e.preventDefault();setZoom(S.zoom*1.2);return}if(mod&&(e.key==='='||e.code==='NumpadAdd')){e.preventDefault();setZoom(S.zoom*1.2);return}if(mod&&(e.key==='-'||e.key==='_'||e.code==='NumpadSubtract')){e.preventDefault();setZoom(S.zoom/1.2);return}if(mod&&key==='a'){e.preventDefault();selectAll();return}if(mod&&key==='d'){e.preventDefault();e.shiftKey?reselectSelection():deselectSelection();return}if(mod&&key==='s'){e.preventDefault();reselectSelection();return}if(mod&&key==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if(mod&&key==='y'){e.preventDefault();redo();return}if(e.code==='Space'){if(!e.repeat){e.preventDefault();if(e.target===document.body||e.target===canvas){S.pan=true;canvas.style.cursor='grab'}}return}const map={v:'move',h:'hand',w:'wand',m:e.shiftKey?'ellipse-select':'select',l:e.shiftKey?({'lasso':'polygon-lasso','polygon-lasso':'magnetic-lasso'}[S.tool]||'lasso'):'lasso',t:'text',c:'crop',b:'brush',e:'eraser',g:'fill',i:'eyedrop'};if(map[key])setTool(map[key]);if(e.key==='Escape'){S.select=null;S.wandMask=null;S.selectionBoundary=null;S.previousSelection=null;S.polygonPoints=[];pointerState=null;updateSelectionBox();$('#helpModal').classList.add('hidden')}});
window.addEventListener('keyup',e=>{if(e.code==='Space'){S.pan=false;setTool(S.tool)}if(e.key==='Enter'&&S.polygonPoints.length>=3&&S.tool==='polygon-lasso')commitPolygon()});canvas.addEventListener('dblclick',e=>{if(S.tool==='polygon-lasso'){e.preventDefault();commitPolygon()}});
$('#canvasWorkspace').addEventListener('dragover',e=>e.preventDefault());$('#canvasWorkspace').addEventListener('drop',e=>{e.preventDefault();const fs=[...e.dataTransfer.files];if(fs.some(f=>f.type==='image/png'||/\.png$/i.test(f.name)))importFiles(fs,'Dropped sprites')});
new ResizeObserver(()=>centerStage()).observe(canvasWorkspace);$('#timelineCount').textContent='0 frames';setTool('move');renderTimeline();updateHistoryButtons();






